1	/**
2	 * Shared primitives for the docs and i18n translation pipelines.
3	 *
4	 * Both pipelines shell out to an AI CLI that reads a prompt via stdin and writes a response to
5	 * stdout. This module owns the spawn mechanism, JSON response parser, and the content-addressed
6	 * translation-memory core so neither pipeline has to duplicate them.
7	 *
8	 * @module
9	 */
10	import { createHash } from "node:crypto";
11	import { existsSync, mkdirSync, readdirSync, readFileSync, writeFileSync } from "node:fs";
12	import { dirname, join, resolve } from "node:path";
13	import { spawn } from "node:child_process";
14	
15	// The configurable drift-severity policy every `check-drift` script reports through. Re-exported here
16	// so a checker needs one import for both the translation primitives and the gate.
17	export {
18	  DEFAULT_DRIFT_POLICY,
19	  DriftReporter,
20	  loadDriftPolicy,
21	  parseDriftPolicy,
22	  repoRelative,
23	  resetDriftPolicyCache,
24	  resolveDriftSeverity,
25	  resolveTier,
26	  type DriftFinding,
27	  type DriftPolicy,
28	  type DriftReporterOptions,
29	  type DriftSeverity,
30	  type SurfacePolicy,
31	} from "./drift-policy.ts";
32	
33	/**
34	 * Pull the first `{…}` JSON object out of a model response, tolerating surrounding prose or code
35	 * fences. Returns `null` when no valid object is found.
36	 */
37	export function extractJsonObject(raw: string): Record<string, unknown> | null {
38	  const start = raw.indexOf("{");
39	  const end = raw.lastIndexOf("}");
40	  if (start === -1 || end <= start) return null;
41	  try {
42	    const parsed = JSON.parse(raw.slice(start, end + 1)) as unknown;
43	    return typeof parsed === "object" && parsed !== null
44	      ? (parsed as Record<string, unknown>)
45	      : null;
46	  } catch {
47	    return null;
48	  }
49	}
50	
51	/**
52	 * Spawn an AI command, send `prompt` via stdin, and resolve with the trimmed stdout.
53	 *
54	 * The caller is responsible for building `args` — the convention is that `-p` is always the final
55	 * arg so the `agy-wrapper.sh` can strip it and forward the prompt via agy's own `-p` flag.
56	 *
57	 * @param command - The executable (e.g. `"claude"` or a path to `agy-wrapper.sh`).
58	 * @param args    - Extra flags plus the terminal `-p` sentinel (e.g. `["--model", "x", "-p"]`).
59	 * @param prompt  - The prompt text; written to the child's stdin then the pipe is closed.
60	 * @param context - Optional label for the error message (e.g. `"locale 'hu'"` or `"foo.md"`).
61	 */
62	export function spawnPrompt(
63	  command: string,
64	  args: string[],
65	  prompt: string,
66	  context?: string,
67	): Promise<string> {
68	  return new Promise((resolve, reject) => {
69	    const child = spawn(command, args, { stdio: ["pipe", "pipe", "pipe"] });
70	    let out = "";
71	    let err = "";
72	    child.stdout.setEncoding("utf8");
73	    child.stderr.setEncoding("utf8");
74	    child.stdout.on("data", (chunk: string) => {
75	      out += chunk;
76	    });
77	    child.stderr.on("data", (chunk: string) => {
78	      err += chunk;
79	    });
80	    // Cast to a minimal shape: ChildProcessByStdio omits .on() in @types/node ≥ 22.
81	    const proc = child as unknown as {
82	      on(event: "error", listener: (e: Error) => void): void;
83	      on(event: "close", listener: (code: number | null) => void): void;
84	    };
85	    proc.on("error", reject);
86	    proc.on("close", (code) => {
87	      if (code !== 0) {
88	        const where = context ? ` for ${context}` : "";
89	        reject(new Error(`AI command exited ${String(code)}${where}: ${err.trim()}`));
90	      } else {
91	        resolve(out.trimEnd());
92	      }
93	    });
94	    child.stdin.end(prompt);
95	  });
96	}
97	
98	// ── Translation memory ────────────────────────────────────────────────────────
99	
100	interface CacheFile {
101	  version: 1;
102	  entries: Record<string, string>;
103	}
104	
105	/**
106	 * Content-addressed translation cache backed by a committed JSON file.
107	 *
108	 * Pipeline-specific facades (docs, i18n) wrap this with their own key-construction logic and
109	 * factory method — neither `get` nor `set` here computes a key; callers pass pre-computed hashes.
110	 *
111	 * Set `prune: true` (docs) to discard entries not touched this session on `save()` — keeps the
112	 * cache from accumulating stale keys after source content is deleted. Leave it off (i18n) to
113	 * preserve all entries across runs.
114	 */
115	export class TranslationMemory {
116	  readonly path: string;
117	  private readonly _entries: Map<string, string>;
118	  private readonly _prune: boolean;
119	  private readonly _used = new Set<string>();
120	  hits = 0;
121	
122	  private constructor(path: string, entries: Map<string, string>, prune: boolean) {
123	    this.path = path;
124	    this._entries = entries;
125	    this._prune = prune;
126	  }
127	
128	  /** Open (or create) a memory backed by `path`. */
129	  static open(path: string, options?: { prune?: boolean }): TranslationMemory {
130	    if (!existsSync(path)) return new TranslationMemory(path, new Map(), options?.prune ?? false);
131	    const parsed = JSON.parse(readFileSync(path, "utf8")) as CacheFile;
132	    return new TranslationMemory(
133	      path,
134	      new Map(Object.entries(parsed.entries ?? {})),
135	      options?.prune ?? false,
136	    );
137	  }
138	
139	  /** Return a cached value and record a hit; returns `undefined` on a miss. */
140	  get(key: string): string | undefined {
141	    const val = this._entries.get(key);
142	    if (val !== undefined) {
143	      this._used.add(key);
144	      this.hits++;
145	    }
146	    return val;
147	  }
148	
149	  /** Store a translated value and mark the key as used. */
150	  set(key: string, value: string): void {
151	    this._entries.set(key, value);
152	    this._used.add(key);
153	  }
154	
155	  /** True when the key is present (no counter side-effects). */
156	  has(key: string): boolean {
157	    return this._entries.has(key);
158	  }
159	
160	  /** Iterate all stored keys. */
161	  keys(): IterableIterator<string> {
162	    return this._entries.keys();
163	  }
164	
165	  /** Write entries to disk, optionally pruning to only the keys touched this session. */
166	  save(): void {
167	    const source = this._prune ? [...this._used].sort() : [...this._entries.keys()].sort();
168	    const out: Record<string, string> = {};
169	    for (const key of source) {
170	      const val = this._entries.get(key);
171	      if (val !== undefined) out[key] = val;
172	    }
173	    mkdirSync(dirname(this.path), { recursive: true });
174	    writeFileSync(this.path, `${JSON.stringify({ version: 1, entries: out }, null, 2)}\n`);
175	  }
176	}
177	
178	/** Compute a SHA-256 hex digest of `input`. */
179	export function sha256(input: string): string {
180	  return createHash("sha256").update(input).digest("hex");
181	}
182	
183	/**
184	 * True when `translated` is just `source` echoed back (trimmed, case-insensitive) — the shape a
185	 * silently-failing AI adapter tends to produce: it exits 0 with syntactically valid JSON, so nothing
186	 * else flags the run as unhealthy.
187	 */
188	export function isPassthroughTranslation(source: string, translated: string): boolean {
189	  return source.trim().toLowerCase() === translated.trim().toLowerCase();
190	}
191	
192	/**
193	 * A key's verbatim policy: `"required"` copies the English source without invoking the translator,
194	 * while `"allow"` permits every locale to legitimately match the English source after translation;
195	 * otherwise a per-tier list of locale patterns (an exact code like `"en-GB"`, a `"prefix*"` glob, or
196	 * `"*"` for every locale) decides the outcome for a locale whose response is identical to the
197	 * source — `required` skips translation and copies it, `allow` caches it silently, `warn` caches it
198	 * but logs a note, and an explicit `error` tier match forces retranslation even over a
199	 * caller-supplied default policy. A locale matched by none of the tiers falls through to that default
200	 * policy (see {@link resolveVerbatimAction}); still unmatched is the strict default: not cached,
201	 * retried next run. Omitting `verbatim` entirely is equivalent to no tiers at all.
202	 */
203	export type VerbatimPolicy =
204	  | "required"
205	  | "allow"
206	  | {
207	      required?: readonly string[];
208	      allow?: readonly string[];
209	      warn?: readonly string[];
210	      error?: readonly string[];
211	    };
212	
213	/** One `src/i18n.json` entry: a plain translatable string, or a string plus its verbatim policy. */
214	export type I18nSourceEntry = string | { string: string; verbatim?: VerbatimPolicy };
215	
216	/** A raw `src/i18n.json`-shaped object, before {@link parseI18nSource} flattens it. */
217	export type RawI18nSource = Record<string, I18nSourceEntry>;
218	
219	/** {@link parseI18nSource}'s result: flattened strings plus each key's declared verbatim policy. */
220	export interface ParsedI18nSource {
221	  strings: Record<string, string>;
222	  verbatim: Record<string, VerbatimPolicy>;
223	}
224	
225	/**
226	 * Flatten a `src/i18n.json` source into its plain strings and any per-key `verbatim` policy, so a
227	 * package can declare "this key is allowed to stay untranslated (for some/all locales)" inline with
228	 * its source string. `{ "datePlaceholder": { "string": "yyyy-mm-dd", "verbatim": "allow" } }` and
229	 * `{ "dateLabel": "Date" }` both parse cleanly — a plain string entry just has no policy.
230	 */
231	export function parseI18nSource(raw: RawI18nSource): ParsedI18nSource {
232	  const strings: Record<string, string> = {};
233	  const verbatim: Record<string, VerbatimPolicy> = {};
234	  for (const [key, entry] of Object.entries(raw)) {
235	    if (typeof entry === "string") {
236	      strings[key] = entry;
237	    } else {
238	      strings[key] = entry.string;
239	      if (entry.verbatim !== undefined) verbatim[key] = entry.verbatim;
240	    }
241	  }
242	  return { strings, verbatim };
243	}
244	
245	/** True when `locale` matches a verbatim-policy pattern: an exact code, a `"prefix*"` glob, or `"*"`. */
246	function localeMatchesPattern(pattern: string, locale: string): boolean {
247	  if (pattern === "*") return true;
248	  return pattern.endsWith("*") ? locale.startsWith(pattern.slice(0, -1)) : pattern === locale;
249	}
250	
251	/**
252	 * Derive one `"<lang>*"` glob per unique base language present in `locales` (e.g. the ~47 keys of
253	 * `CANVAS_LOCALES`), for building a {@link VerbatimPolicy}'s `allow`/`warn`/`error` lists without
254	 * hand-typing every regional variant. `"en-GB"` and `"en-AU"` both collapse to `"en*"`; a locale
255	 * with no region subtag (e.g. `"hu"`) becomes `"hu*"` too. Returned sorted and deduped — callers
256	 * pick which families go in which tier, e.g. `{ allow: localeFamilyGlobs(["en-GB", "en-AU"]) }`.
257	 */
258	export function localeFamilyGlobs(locales: readonly string[]): string[] {
259	  const families = new Set(locales.map((locale) => locale.split("-")[0]));
260	  return [...families].sort().map((lang) => `${lang}*`);
261	}
262	
263	/** Render `keys` as an indented bullet list (one per line) for legible multi-key console warnings. */
264	function formatKeyList(keys: readonly string[]): string {
265	  return keys.map((key) => `  - ${key}`).join("\n");
266	}
267	
268	/** Check a single non-shorthand policy's tiers for `locale`, with explicit errors taking precedence. */
269	function matchPolicyTiers(
270	  policy: Exclude<VerbatimPolicy, "required" | "allow">,
271	  locale: string,
272	): "required" | "allow" | "warn" | "error" | undefined {
273	  if (policy.error?.some((p) => localeMatchesPattern(p, locale))) return "error";
274	  if (policy.required?.some((p) => localeMatchesPattern(p, locale))) return "required";
275	  if (policy.allow?.some((p) => localeMatchesPattern(p, locale))) return "allow";
276	  if (policy.warn?.some((p) => localeMatchesPattern(p, locale))) return "warn";
277	  return undefined;
278	}
279	
280	/**
281	 * Resolve what a passthrough (identical-to-source) value should do for `locale`, given a key's
282	 * declared `policy` and an optional `defaultPolicy` fallback. `policy`'s own tiers are checked
283	 * first (its `error` tier always wins, even over a permissive default); if none of its tiers match
284	 * `locale`, `defaultPolicy`'s tiers are checked the same way. Still no match (or both are
285	 * `undefined`) is the strict default: `"error"`.
286	 */
287	export function resolveVerbatimAction(
288	  policy: VerbatimPolicy | undefined,
289	  locale: string,
290	  defaultPolicy?: VerbatimPolicy,
291	): "required" | "allow" | "warn" | "error" {
292	  if (policy === "required") return "required";
293	  if (policy === "allow") return "allow";
294	  const matched = policy && matchPolicyTiers(policy, locale);
295	  if (matched !== undefined) return matched;
296	  if (defaultPolicy === "required") return "required";
297	  if (defaultPolicy === "allow") return "allow";
298	  return (defaultPolicy && matchPolicyTiers(defaultPolicy, locale)) ?? "error";
299	}
300	
301	// ── CLI translation runner ────────────────────────────────────────────────────
302	
303	/** Options for {@link runI18nTranslationCli}. */
304	export interface I18nTranslationOptions {
305	  /** Label shown in the startup banner, e.g. `"@pantoken/scaffold strings"`. */
306	  label: string;
307	  /** The English source key → string map to translate from. */
308	  source: Record<string, string>;
309	  /** Target locale codes to translate into (`"en"` is always skipped, it's the source). */
310	  targetLocales: string[];
311	  /** Resolve the on-disk cache path for a locale, e.g. `i18n-cache/\${locale}.json`. */
312	  cachePath: (locale: string) => string;
313	  /**
314	   * Whether `key` is already present in `cache`. Defaults to a plain `key in cache` check;
315	   * override to also recognize a legacy hash-keyed cache (see `sha256`).
316	   */
317	  isCached?: (key: string, cache: Record<string, string>) => boolean;
318	  /**
319	   * Read `key`'s current cached value, for the passthrough audit. Defaults to `cache[key]`;
320	   * override alongside a custom `isCached` when a legacy cache stores values under `sha256(key)`.
321	   */
322	  cachedValue?: (key: string, cache: Record<string, string>) => string | undefined;
323	  /**
324	   * Per-key verbatim policies (see {@link VerbatimPolicy}), typically produced by
325	   * {@link parseI18nSource} from the same `src/i18n.json` `source` came from. For a locale not
326	   * covered by a key's own tiers, resolution falls through to `defaultVerbatim` (if set), then the
327	   * strict default: identical output is treated as a likely AI failure for every locale.
328	   */
329	  verbatim?: Record<string, VerbatimPolicy>;
330	  /**
331	   * A fallback {@link VerbatimPolicy} applied to every locale not covered by a key's own `verbatim`
332	   * tiers — e.g. a blanket "these language families are close enough to English that an identical
333	   * response isn't necessarily a translator failure" rule, built with {@link localeFamilyGlobs}. A
334	   * key's own `error` tier still wins over this default for a matching locale.
335	   */
336	  defaultVerbatim?: VerbatimPolicy;
337	}
338	
339	/**
340	 * Drop any entry from `cache` whose value is an untranslated echo of its English source and whose
341	 * key resolves to the `"error"` tier for `locale`, so it's retranslated this run instead of sitting
342	 * there looking done forever. A `"warn"`-tier match is left cached but reported. Returns the reset
343	 * and warned keys.
344	 */
345	function resetPassthroughEntries(
346	  cache: Record<string, string>,
347	  source: Record<string, string>,
348	  cachedValue: (key: string, cache: Record<string, string>) => string | undefined,
349	  verbatim: Record<string, VerbatimPolicy>,
350	  defaultVerbatim: VerbatimPolicy | undefined,
351	  locale: string,
352	): { reset: string[]; warned: string[] } {
353	  const reset: string[] = [];
354	  const warned: string[] = [];
355	  for (const key of Object.keys(source)) {
356	    const current = cachedValue(key, cache);
357	    if (current === undefined || !isPassthroughTranslation(source[key], current)) continue;
358	    const action = resolveVerbatimAction(verbatim[key], locale, defaultVerbatim);
359	    if (action === "required" || action === "allow") continue;
360	    if (action === "warn") {
361	      warned.push(key);
362	      continue;
363	    }
364	    delete cache[key];
365	    delete cache[sha256(key)];
366	    reset.push(key);
367	  }
368	  return { reset, warned };
369	}
370	
371	/** Translate `locale`'s missing keys (per `isCached`) and merge/save the result into its cache file. */
372	async function translateLocale(
373	  locale: string,
374	  command: string,
375	  commandArgs: string[],
376	  options: I18nTranslationOptions,
377	  isCached: (key: string, cache: Record<string, string>) => boolean,
378	): Promise<void> {
379	  const cacheFile = resolve(options.cachePath(locale));
380	  let cache: Record<string, string>;
381	  try {
382	    cache = JSON.parse(readFileSync(cacheFile, "utf8"));
383	  } catch {
384	    console.log(`Creating new cache for locale: ${locale}`);
385	    cache = {};
386	  }
387	
388	  const cachedValue = options.cachedValue ?? ((key: string, c: Record<string, string>) => c[key]);
389	  const verbatim = options.verbatim ?? {};
390	  const { reset: resetKeys, warned: warnedResetKeys } = resetPassthroughEntries(
391	    cache,
392	    options.source,
393	    cachedValue,
394	    verbatim,
395	    options.defaultVerbatim,
396	    locale,
397	  );
398	  if (resetKeys.length > 0) {
399	    console.warn(
400	      `⚠ ${locale}: reset ${resetKeys.length} previously-cached entr${resetKeys.length === 1 ? "y" : "ies"} that matched the English source (will retry):\n${formatKeyList(resetKeys)}`,
401	    );
402	  }
403	  if (warnedResetKeys.length > 0) {
404	    console.warn(
405	      `⚠ ${locale}: ${warnedResetKeys.length} cached entr${warnedResetKeys.length === 1 ? "y matches" : "ies match"} the English source (verbatim policy: warn):\n${formatKeyList(warnedResetKeys)}`,
406	    );
407	  }
408	
409	  const requiredKeys = new Set(
410	    Object.keys(options.source).filter(
411	      (key) => resolveVerbatimAction(verbatim[key], locale, options.defaultVerbatim) === "required",
412	    ),
413	  );
414	  let copiedRequired = false;
415	  for (const key of requiredKeys) {
416	    const legacyKey = sha256(key);
417	    if (cache[key] !== options.source[key] || legacyKey in cache) copiedRequired = true;
418	    delete cache[legacyKey];
419	    cache[key] = options.source[key];
420	  }
421	
422	  const missingKeys = Object.keys(options.source).filter(
423	    (key) => !requiredKeys.has(key) && !isCached(key, cache),
424	  );
425	  if (missingKeys.length === 0) {
426	    if (copiedRequired) writeFileSync(cacheFile, JSON.stringify(cache, null, 2) + "\n", "utf8");
427	    console.log(`✓ ${locale}: all strings translated`);
428	    return;
429	  }
430	
431	  console.log(`🔄 ${locale}: translating ${missingKeys.length} new string(s)...`);
432	
433	  const stringsList = missingKeys.map((k) => `- "${k}": "${options.source[k]}"`).join("\n");
434	  const prompt = `Translate these UI strings from English into ${locale} (for a CLI):
435	
436	${stringsList}
437	
438	Respond with a JSON object mapping each original key to its translation, using the exact same keys. Only the translations, nothing else.`;
439	
440	  try {
441	    const result = await spawnPrompt(command, [...commandArgs, "-p"], prompt, `locale "${locale}"`);
442	
443	    const translated = extractJsonObject(result);
444	    if (!translated) {
445	      throw new Error(`AI response could not be parsed as JSON for locale "${locale}".`);
446	    }
447	
448	    const suspectKeys: string[] = [];
449	    const warnedKeys: string[] = [];
450	    let saved = 0;
451	    for (const key of missingKeys) {
452	      const value = translated[key];
453	      if (typeof value !== "string" || value.trim().length === 0) {
454	        suspectKeys.push(`${key} (missing or empty)`);
455	        continue;
456	      }
457	      if (isPassthroughTranslation(options.source[key], value)) {
458	        const action = resolveVerbatimAction(verbatim[key], locale, options.defaultVerbatim);
459	        if (action === "error") {
460	          suspectKeys.push(`${key} (identical to source)`);
461	          continue;
462	        }
463	        if (action === "warn") warnedKeys.push(key);
464	      }
465	      cache[key] = value;
466	      saved++;
467	    }
468	    if (suspectKeys.length > 0) {
469	      console.warn(
470	        `⚠ ${locale}: ${suspectKeys.length} response(s) not cached, will retry next run:\n${formatKeyList(suspectKeys)}`,
471	      );
472	    }
473	    if (warnedKeys.length > 0) {
474	      console.warn(
475	        `⚠ ${locale}: ${warnedKeys.length} response(s) identical to the English source (verbatim policy: warn), cached anyway:\n${formatKeyList(warnedKeys)}`,
476	      );
477	    }
478	
479	    writeFileSync(cacheFile, JSON.stringify(cache, null, 2) + "\n", "utf8");
480	    console.log(`✓ ${locale}: saved ${saved} translation(s)\n`);
481	  } catch (err) {
482	    console.error(`❌ Failed to translate for locale ${locale}:`, err);
483	    process.exit(1);
484	  }
485	}
486	
487	/**
488	 * Shell out to an AI CLI to translate every source string missing from each target locale's
489	 * on-disk cache, merging the results back in. Shared by `ai/pantoken-ai/scripts/translate.ts` and
490	 * `packages/scaffold/scripts/translate.ts`, whose i18n CLIs both translate a flat key → string map
491	 * the same way, differing only in where the source strings and cache files come from.
492	 *
493	 * Reads `I18N_TRANSLATION_ADAPTER`/`I18N_TRANSLATION_COMMAND`/`I18N_TRANSLATION_COMMAND_ARGS` env
494	 * vars to choose the model/command, matching both callers' existing conventions.
495	 * `I18N_TRANSLATION_FORCE=1` bypasses `isCached` entirely — every key is retranslated and its
496	 * cached value overwritten, even if already present — for a forced refresh after fixing an adapter
497	 * bug or a bad translation. Exits the process with code 1 if a locale's translation request fails.
498	 */
499	export async function runI18nTranslationCli(options: I18nTranslationOptions): Promise<void> {
500	  const adapter = process.env.I18N_TRANSLATION_ADAPTER || "ai";
501	  const command = process.env.I18N_TRANSLATION_COMMAND ?? "claude";
502	  const commandArgs = (process.env.I18N_TRANSLATION_COMMAND_ARGS ?? "")
503	    .split(" ")
504	    .map((p) => p.trim())
505	    .filter((p) => p.length > 0);
506	  const force = process.env.I18N_TRANSLATION_FORCE === "1";
507	  const isCached = force ? () => false : (options.isCached ?? ((key, cache) => key in cache));
508	
509	  console.log(`📋 Translating ${options.label} (${adapter})\n`);
510	
511	  for (const locale of options.targetLocales) {
512	    if (locale === "en") continue; // Skip English, it's the source
513	    await translateLocale(locale, command, commandArgs, options, isCached);
514	  }
515	
516	  console.log(`✨ All translations complete!`);
517	}
518	
519	// ── Locale bundle codegen ──────────────────────────────────────────────────────
520	
521	/**
522	 * Generate one `LOCALE_<CODE>.ts` module per `<code>.json` file in `<root>/i18n-cache`, plus an
523	 * `index.ts` importing and re-exporting them all as `LOCALES`, into `<outDir>/locales`. Logs a
524	 * one-line summary of the locales it produced (nothing when the cache directory doesn't exist yet).
525	 *
526	 * Shared by `ai/pantoken-ai/scripts/generate.ts` and `packages/scaffold/scripts/generate.ts`, whose
527	 * CLI i18n setups both bake a translated `i18n-cache/` into a generated locale bundle the same way.
528	 *
529	 * @param root - Package root containing `i18n-cache/`.
530	 * @param outDir - The package's `generated/` directory; bundles are written under its `locales/`.
531	 */
532	export function generateLocaleBundles(root: string, outDir: string): void {
533	  const i18nCacheDir = join(root, "i18n-cache");
534	  const localesDir = join(outDir, "locales");
535	  mkdirSync(localesDir, { recursive: true });
536	
537	  const localeMap: Record<string, string> = {};
538	  try {
539	    const cacheFiles = readdirSync(i18nCacheDir);
540	    for (const file of cacheFiles) {
541	      if (!file.endsWith(".json")) continue;
542	      const locale = file.slice(0, -".json".length);
543	      const cachePath = join(i18nCacheDir, file);
544	      const bundle = JSON.parse(readFileSync(cachePath, "utf8"));
545	
546	      // Hyphenated locale tags (e.g. "en-AU") aren't valid JS identifier suffixes.
547	      const varName = `LOCALE_${locale.toUpperCase().replaceAll("-", "_")}`;
548	      const tsContent = `// GENERATED by scripts/generate.ts — do not edit by hand.\nexport const ${varName} = ${JSON.stringify(
549	        bundle,
550	        null,
551	        2,
552	      )} as const;\n`;
553	      writeFileSync(join(localesDir, `${locale}.ts`), tsContent);
554	      localeMap[locale] = varName;
555	    }
556	  } catch {
557	    // i18n-cache directory doesn't exist yet, that's okay
558	  }
559	
560	  const indexContent = `// GENERATED by scripts/generate.ts — do not edit by hand.
561	${Object.entries(localeMap)
562	  .map(([locale, varName]) => `import { ${varName} } from "./${locale}.js";`)
563	  .join("\n")}
564	
565	export const LOCALES: Record<string, Record<string, string>> = {
566	${Object.entries(localeMap)
567	  .map(([locale, varName]) => `  ${JSON.stringify(locale)}: ${varName},`)
568	  .join("\n")}
569	};
570	`;
571	  writeFileSync(join(localesDir, "index.ts"), indexContent);
572	
573	  const locales = Object.keys(localeMap);
574	  if (locales.length > 0) {
575	    console.log(`✓ generated locale bundles for: ${locales.join(", ")}`);
576	  }
577	}
